<style>
:root{
  --paper:#f3ead9; --paper-2:#f8f2e4; --ink:#221d15; --ink-soft:#4a4234;
  --muted:#8b806c; --line:#cbbd9f; --pine:#1d5c47; --red:#b23a20; --gold:#b98a2f;
}
*{margin:0;padding:0;box-sizing:border-box}
@media (prefers-reduced-motion:no-preference){ html{scroll-behavior:smooth} }
body{
  background:var(--paper);
  background-image:radial-gradient(120% 80% at 50% 0%, rgba(255,255,255,.55), transparent 55%),
                   radial-gradient(90% 60% at 80% 100%, rgba(29,92,71,.07), transparent 60%);
  color:var(--ink); font-family:'Newsreader',Georgia,serif; overflow-x:hidden;
}
.mono{font-family:'IBM Plex Mono',monospace}
/* ---------- grain ---------- */
.grain{position:fixed; inset:-120px; pointer-events:none; z-index:60; opacity:.055; mix-blend-mode:multiply;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='0.6'/></svg>");
  animation:grainShift 1.4s steps(4) infinite;
}
@keyframes grainShift{0%{transform:translate(0,0)}25%{transform:translate(-38px,22px)}50%{transform:translate(24px,-30px)}75%{transform:translate(-14px,-18px)}100%{transform:translate(0,0)}}
/* ---------- masthead ---------- */
.masthead{display:flex; justify-content:space-between; align-items:center; gap:16px; padding:14px 28px;
  border-bottom:1px solid var(--ink); position:relative; font:500 10.5px 'IBM Plex Mono'; letter-spacing:.2em; text-transform:uppercase; color:var(--ink-soft);
}
.masthead::after{content:""; position:absolute; left:0; right:0; bottom:-4px; height:1px; background:var(--ink)}
.mast-mid{color:var(--muted)}
/* ---------- invoice header ---------- */
.invoice{max-width:1240px; margin:0 auto; padding:64px 28px 60px; display:grid; grid-template-columns:1.25fr .9fr; gap:56px; align-items:end}
.inv-kicker{font:500 11px 'IBM Plex Mono'; letter-spacing:.24em; text-transform:uppercase; color:var(--muted); margin-bottom:22px}
.inv-kicker::before{content:"◆ "; color:var(--red)}
.inv-bill{font-family:'Fraunces',serif; font-weight:900; font-size:clamp(4.6rem,15vw,12.5rem); line-height:.86; letter-spacing:-.02em; font-variation-settings:'opsz' 144;
}
.inv-bill .dot{color:var(--red)}
.inv-of{margin-top:26px; font-family:'Fraunces'; font-weight:600; font-size:clamp(1.5rem,3.2vw,2.5rem); letter-spacing:.14em}
.inv-of-sub{display:block; margin-top:6px; font:italic 400 1.05rem 'Newsreader'; letter-spacing:0; color:var(--muted)}
.inv-sub{margin-top:22px; font-size:1.12rem; line-height:1.7; color:var(--ink-soft); max-width:44ch}
.lm{display:block; overflow:hidden}
.lm-i{display:block}
.js .invoice .lm-i{transform:translateY(115%); transition:transform .9s cubic-bezier(.22,1,.36,1)}
.invoice.in .lm-i{transform:none}
.invoice .inv-sub .lm:nth-child(2) .lm-i{transition-delay:.14s}
.invoice .inv-of .lm-i{transition-delay:.08s}
.inv-fields{border:1px solid var(--ink); background:var(--paper-2); padding:26px 26px 22px; position:relative; box-shadow:6px 6px 0 rgba(34,29,21,.12)}
.field{display:grid; grid-template-columns:96px 1fr; gap:12px; padding:11px 0; border-bottom:1px dashed var(--line); align-items:baseline}
.f-label{font:500 9.5px 'IBM Plex Mono'; letter-spacing:.2em; text-transform:uppercase; color:var(--muted)}
.f-val{font:500 1rem/1.45 'Newsreader'}
.total{margin-top:16px; display:flex; justify-content:space-between; gap:10px; font:600 11.5px 'IBM Plex Mono'; letter-spacing:.16em; text-transform:uppercase;
  background:var(--ink); color:var(--paper); padding:12px 14px}
.total b{color:var(--gold); font-weight:600}
.barcode-bars{margin-top:16px; height:36px;
  background:repeating-linear-gradient(90deg,var(--ink) 0 2px,transparent 2px 4px,var(--ink) 4px 5px,transparent 5px 10px,var(--ink) 10px 13px,transparent 13px 15px,var(--ink) 15px 16px,transparent 16px 21px)}
.barcode span{display:block; margin-top:7px; font:500 9px 'IBM Plex Mono'; letter-spacing:.34em; color:var(--muted)}
/* stamps */
.stamp{display:inline-block; font:600 12px/1 'IBM Plex Mono'; letter-spacing:.3em; text-transform:uppercase; color:var(--red);
  border:2.5px solid var(--red); outline:1px solid var(--red); outline-offset:3px; padding:9px 15px 8px; mix-blend-mode:multiply; opacity:.92; white-space:nowrap}
.stamp-green{color:var(--pine); border-color:var(--pine); outline-color:var(--pine)}
.stamp-wrap{position:absolute; right:-16px; top:-22px}
.js .inv-stamp{opacity:0}
.invoice.in .inv-stamp{animation:thump .55s cubic-bezier(.2,1.4,.4,1) .7s forwards}
@keyframes thump{0%{opacity:0; transform:rotate(16deg) scale(2.2)}70%{opacity:.92; transform:rotate(8deg) scale(.94)}100%{opacity:.92; transform:rotate(8deg) scale(1)}}
/* ---------- ticker ---------- */
.ticker{border-top:1px solid var(--ink); border-bottom:1px solid var(--ink); background:var(--ink); color:var(--paper); overflow:hidden; padding:10px 0}
.ticker-track{display:flex; width:max-content; animation:tick 38s linear infinite}
.t-half{display:flex; align-items:center; white-space:nowrap}
.t-item{font:500 11px 'IBM Plex Mono'; letter-spacing:.22em; text-transform:uppercase; padding:0 26px}
.t-sep{color:var(--gold); font-size:10px}
@keyframes tick{to{transform:translateX(-50%)}}
/* ---------- layout ---------- */
.layout{max-width:1240px; margin:0 auto; padding:56px 28px 30px; display:grid; grid-template-columns:290px minmax(0,1fr); gap:56px; align-items:start}
.rail{position:sticky; top:20px; border:1px solid var(--ink); background:var(--paper-2); display:flex; flex-direction:column; max-height:calc(100vh - 40px)}
.rail-head{padding:13px 16px; border-bottom:1px solid var(--ink); font-size:10px; letter-spacing:.22em; text-transform:uppercase; display:flex; justify-content:space-between; color:var(--ink-soft)}
.rail-head b{color:var(--red); font-weight:600}
.toc{overflow-y:auto; scrollbar-width:thin; scrollbar-color:var(--line) transparent}
.toc a{display:grid; grid-template-columns:34px 1fr; gap:10px; padding:9px 16px; text-decoration:none; color:var(--ink-soft);
  border-bottom:1px solid rgba(203,189,159,.5); font:500 .95rem 'Newsreader'; transition:background .25s,color .25s,transform .25s}
.toc a:hover{background:rgba(29,92,71,.09); color:var(--ink); transform:translateX(3px)}
.t-num{font:500 10px 'IBM Plex Mono'; letter-spacing:.1em; color:var(--muted); padding-top:2px}
.toc a.active{background:var(--ink); color:var(--paper)}
.toc a.active .t-num{color:var(--gold)}
.rail-progress{border-top:1px solid var(--ink); padding:14px 16px 16px}
.rp-top{display:flex; justify-content:space-between; font:500 9.5px 'IBM Plex Mono'; letter-spacing:.18em; text-transform:uppercase; color:var(--muted); margin-bottom:9px}
#rpLabel{color:var(--pine)}
.rp-bar{height:7px; border:1px solid var(--ink); position:relative}
#rpFill{position:absolute; inset:0; width:4%; background:var(--pine); transition:width .35s ease}
/* ---------- entries ---------- */
.js .reveal{opacity:0; transform:translateY(26px); transition:opacity .8s ease, transform .8s cubic-bezier(.22,1,.36,1)}
.js .reveal.in{opacity:1; transform:none}
.entry{position:relative; border:1px solid var(--ink); background:var(--paper-2); padding:30px 34px 28px;
