.entry:hover{transform:translate(-2px,-2px); box-shadow:9px 9px 0 rgba(34,29,21,.14)}
.e-head{display:flex; gap:22px; align-items:flex-start; border-bottom:1px solid var(--line); padding-bottom:18px; margin-bottom:24px}
.e-num{font:900 56px/.9 'Fraunces'; letter-spacing:-.02em; transition:color .35s}
.entry:hover .e-num{color:var(--red)}
.e-of{font:500 11px 'IBM Plex Mono'; color:var(--muted); letter-spacing:.14em; margin-top:8px; display:block}
.e-tag{font:500 9.5px 'IBM Plex Mono'; letter-spacing:.2em; text-transform:uppercase; color:var(--pine); margin-bottom:8px}
.e-name{font:900 clamp(1.65rem,3vw,2.35rem)/1.06 'Fraunces'; letter-spacing:-.01em;
  background:linear-gradient(var(--red),var(--red)) no-repeat 0 100%/0 2px; transition:background-size .5s ease}
.entry:hover .e-name{background-size:100% 2px}
.e-body{display:grid; grid-template-columns:minmax(0,1fr) 190px; gap:32px}
.verse{font:500 clamp(1.2rem,1.9vw,1.55rem)/1.62 'Newsreader'; padding-top:4px}
.js .verse .lm-i{transform:translateY(115%); transition:transform .8s cubic-bezier(.22,1,.36,1)}
.entry.in .verse .lm-i{transform:none}
.entry .verse .lm:nth-child(1) .lm-i{transition-delay:.05s}
.entry .verse .lm:nth-child(2) .lm-i{transition-delay:.13s}
.entry .verse .lm:nth-child(3) .lm-i{transition-delay:.21s}
.entry .verse .lm:nth-child(4) .lm-i{transition-delay:.29s}
.entry .verse .lm:nth-child(5) .lm-i{transition-delay:.37s}
.verse p:last-child .lm-i{font-style:italic; background:linear-gradient(transparent 64%, rgba(178,58,32,.18) 64%)}
.e-side{display:flex; flex-direction:column; gap:14px}
.photo{border:1px solid var(--ink); overflow:hidden; aspect-ratio:4/5; position:relative; background:#d8ccb2; flex:0 0 auto}
.photo img{width:100%; height:100%; object-fit:cover; filter:sepia(.55) contrast(1.02) brightness(.97) saturate(.85);
  animation:breathe 16s ease-in-out infinite alternate; transition:filter .5s}
.entry:hover .photo img{filter:sepia(.12) contrast(1.02) brightness(1)}
@keyframes breathe{from{transform:scale(1.05)}to{transform:scale(1.15) translate(-2%,-2%)}}
.photo figcaption{position:absolute; left:0; right:0; bottom:0; background:rgba(34,29,21,.85); color:var(--paper);
  font:500 8.5px 'IBM Plex Mono'; letter-spacing:.2em; text-transform:uppercase; padding:5px 8px}
.note{font:italic 400 .95rem/1.55 'Newsreader'; color:var(--ink-soft); padding-left:12px; border-left:2px solid var(--red)}
.n-label{font:600 9px 'IBM Plex Mono'; font-style:normal; letter-spacing:.24em; text-transform:uppercase; color:var(--red); display:block; margin-bottom:5px}
.e-stamp{position:absolute; top:20px; right:24px; font-size:10px; padding:6px 11px 5px}
.js .e-stamp{opacity:0}
.entry.in .e-stamp{animation:thump2 .5s cubic-bezier(.2,1.4,.4,1) .6s forwards}
@keyframes thump2{0%{opacity:0; transform:rotate(-18deg) scale(2.1)}70%{opacity:.9; transform:rotate(-7deg) scale(.94)}100%{opacity:.9; transform:rotate(-7deg) scale(1)}}
.perf{height:44px; position:relative}
.perf::before{content:""; position:absolute; top:50%; left:0; right:0; border-top:2px dashed rgba(34,29,21,.32)}
.perf::after{content:""; position:absolute; top:50%; left:50%; width:9px; height:9px; background:var(--paper); border:1px solid rgba(34,29,21,.45);
  transform:translate(-50%,-50%) rotate(45deg)}
/* ---------- memo interlude ---------- */
.memo{display:grid; grid-template-columns:1fr 1fr; border:1px solid var(--ink); background:var(--paper-2); margin:64px 0; box-shadow:5px 5px 0 rgba(34,29,21,.1)}
.memo-letter{padding:32px 34px; border-right:1px dashed var(--line); font:400 1.04rem/1.75 'Newsreader'; color:var(--ink-soft)}
.memo-head{font:600 11px 'IBM Plex Mono'; letter-spacing:.26em; text-transform:uppercase; color:var(--red); margin-bottom:18px; display:inline-block; padding-bottom:10px; border-bottom:2px solid var(--ink)}
.memo-table{padding:32px 34px}
.memo-table table{width:100%; border-collapse:collapse}
.memo-table th{font:600 9.5px 'IBM Plex Mono'; letter-spacing:.18em; text-transform:uppercase; color:var(--muted); text-align:left; padding:8px 10px; border-bottom:2px solid var(--ink)}
.memo-table td{padding:9px 10px; border-bottom:1px solid rgba(203,189,159,.55); font:400 .93rem 'Newsreader'; transition:background .2s}
.memo-table td:first-child{font-weight:600}
