.memo-table tbody tr:hover td{background:rgba(29,92,71,.07)}
/* ---------- terms ---------- */
.terms{border:1px solid var(--ink); background:var(--paper-2); padding:36px 38px; margin:0 0 64px; box-shadow:5px 5px 0 rgba(34,29,21,.1)}
.terms-title{font:900 clamp(1.8rem,3.2vw,2.6rem) 'Fraunces'; margin-bottom:6px}
.terms-title::before{content:"§ "; color:var(--red)}
.terms-sub{font:italic 400 1rem 'Newsreader'; color:var(--muted); margin-bottom:24px}
.terms-grid{display:grid; grid-template-columns:1fr 1fr; gap:26px; font:400 11.5px/2 'IBM Plex Mono'; color:var(--ink-soft)}
.terms-grid p{padding-left:2.2em; text-indent:-2.2em}
.terms-grid p b{color:var(--pine); font-weight:600}
