.foot-sig{display:flex; align-items:flex-end; gap:20px; margin-bottom:32px; flex-wrap:wrap}
.sig{font:700 3rem/1 'Caveat'; transform:rotate(-3deg); border-bottom:1px solid rgba(34,29,21,.4); padding:0 14px 4px}
.sig-cap{font:500 10px 'IBM Plex Mono'; letter-spacing:.18em; text-transform:uppercase; color:var(--muted); padding-bottom:8px}
.colophon{font:italic 400 .95rem/1.75 'Newsreader'; color:var(--muted); max-width:64ch}
