            <tr><td>Wave</td><td>A billow; a break</td><td>09</td></tr>
            <tr><td>Bell</td><td>A bell (Scots “bill”); and its bellman</td><td>05 · 06</td></tr>
            <tr><td>Hayhook</td><td>A billhook</td><td>08</td></tr>
            <tr><td>Goat</td><td>A billy</td><td>21</td></tr>
            <tr><td>Cue ball</td><td>“The bill,” in pool</td><td>18</td></tr>
